      emoji.dataset.boostEmoji = "";
      emoji.setAttribute("aria-label", "插入表情");
      emoji.append(this.#iconNode("smile"));
      emoji.hidden = !this.#emojiMenu;
      const submit = this.#document.createElement("button");
