      this.#status.classList.toggle("warning", total !== 100);
      this.#status.classList.toggle("balanced", total === 100 && !changed);
      this.#status.textContent = total !== 100 ? `${modeLabel(this.#mode)}五区当前合计 ${total}%，必须为 100% 才能保存。` : currentChanged ? `${modeLabel(this.#mode)}正在实时预览；另一个形态的草稿也会统一保存。` : changed > 0 ? `${modeLabel(this.#mode)}当前未改；另一个形态有 ${changed} 项待保存。` : `${modeLabel(this.#mode)}当前配置已应用。`;
